# Tiếng Hàn Mr Lee - Hangul (Bài 0) installer
# Windows PowerShell 5.1 or PowerShell 7; no third-party modules.
# Usage: powershell -ExecutionPolicy Bypass -File .\CAI-BANG-CHU-CAI-HANGUL.ps1
param([string]$WebsitePath = (Get-Location).Path)
$ErrorActionPreference = 'Stop'
$websiteRoot = [System.IO.Path]::GetFullPath($WebsitePath)
if (-not (Test-Path -LiteralPath (Join-Path $websiteRoot 'index.html') -PathType Leaf)) {
  throw 'Khong tim thay index.html trong thu muc website. Mo Terminal VS Code o dung thu muc truoc khi chay.'
}
if (-not (Test-Path -LiteralPath (Join-Path $websiteRoot 'bai-hoc.html') -PathType Leaf)) {
  throw 'Khong tim thay bai-hoc.html trong thu muc website. Khong sua file.'
}
$utf8 = New-Object System.Text.UTF8Encoding($false)
function Read-WebsiteFile([string]$filename) {
  return [System.IO.File]::ReadAllText((Join-Path $websiteRoot $filename), [System.Text.Encoding]::UTF8)
}
function Write-WebsiteFile([string]$filename, [string]$contents) {
  [System.IO.File]::WriteAllText((Join-Path $websiteRoot $filename), $contents, $utf8)
}
# Preflight must finish before changing files.
$lessonBefore = Read-WebsiteFile 'bai-hoc.html'
if (($lessonBefore -notmatch 'id="mrlee-hangul-entry"') -and ($lessonBefore -notmatch '(?i)<main\b[^>]*>')) {
  throw 'Khong nhan dien duoc the <main> trong bai-hoc.html. Khong sua file.'
}
$roadmapPresent = Test-Path -LiteralPath (Join-Path $websiteRoot 'lo-trinh-1-6.html') -PathType Leaf
if ($roadmapPresent) { $roadmapBefore = Read-WebsiteFile 'lo-trinh-1-6.html' }
if ($roadmapPresent -and ($roadmapBefore -notmatch 'id="mrlee-hangul-entry"') -and ($roadmapBefore -notmatch '(?i)<main\b[^>]*>')) {
  throw 'Khong nhan dien duoc the <main> trong lo-trinh-1-6.html. Khong sua file.'
}
# Backups stay OUTSIDE Git repo.
$backupBase = Join-Path ([System.IO.Path]::GetTempPath()) 'MrLee-Hangul-backups'
$backupDir = Join-Path $backupBase ((Get-Date -Format 'yyyyMMdd-HHmmss') + '-' + [guid]::NewGuid().ToString('N').Substring(0,6))
New-Item -ItemType Directory -Force -Path $backupDir | Out-Null
foreach ($filename in @('bang-chu-cai-tieng-han.html','bai-hoc.html','lo-trinh-1-6.html')) {
  $fullPath = Join-Path $websiteRoot $filename
  if (Test-Path -LiteralPath $fullPath -PathType Leaf) {
    Copy-Item -LiteralPath $fullPath -Destination (Join-Path $backupDir $filename) -Force
  }
}
