$insertBlock = @'
<!-- MRLEE-HANGUL-ENTRY-V1 -->
<section id="mrlee-hangul-entry" aria-labelledby="mrlee-hangul-title" style="margin:19px auto 25px; padding:20px 22px; border-radius:18px; border:1px solid #c6d9ed; background:linear-gradient(110deg,#eef6ff 0%,#fff9f5 100%); box-shadow:0 8px 24px rgba(20,48,82,.06); color:#153452; font-family:'Be Vietnam Pro','Noto Sans KR',Arial,sans-serif;">
