    </div>
    <a href="bang-chu-cai-tieng-han.html" style="display:inline-block;background:#102b4d;color:white;text-decoration:none;border-radius:12px;padding:12px 18px;font-weight:800;font-size:13px;white-space:nowrap;">Học bảng chữ cái →</a>
  </div>
</section>
<!-- /MRLEE-HANGUL-ENTRY-V1 -->
'@
function Patch-HangulLink([string]$content) {
  if ($content -match 'id="mrlee-hangul-entry"') { return $content }
  $found = [regex]::Match($content,'(?i)<main\b[^>]*>')
  if (-not $found.Success) { throw 'Khong tim thay vi tri chen bai Hangul.' }
  $point = $found.Index + $found.Length
  return $content.Substring(0,$point) + "`r`n" + $insertBlock + "`r`n" + $content.Substring($point)
}
Write-WebsiteFile 'bang-chu-cai-tieng-han.html' $page
Write-WebsiteFile 'bai-hoc.html' (Patch-HangulLink $lessonBefore)
if ($roadmapPresent) { Write-WebsiteFile 'lo-trinh-1-6.html' (Patch-HangulLink $roadmapBefore) }
Write-Host 'SUCCESS: Them Bai 0 - Bang chu cai tieng Han vao BAI HOC va LO TRINH 1-6 (neu co).' -ForegroundColor Green
Write-Host ('Trang moi: ' + (Join-Path $websiteRoot 'bang-chu-cai-tieng-han.html'))
Write-Host ('Sao luu file cu: ' + $backupDir) -ForegroundColor Cyan
Write-Host 'Cac file index.html, 9 anh banner, Firebase va vi diem KHONG bi thay doi.'
